#!/usr/bin/env bash
# Grant the sandboxed macOS desktop build the entitlements it needs:
#   * com.apple.security.network.client              -> reach your gpix server
#     (without it: SocketException ... Operation not permitted, errno = 1)
#   * com.apple.security.files.user-selected.read-write -> open/save file dialogs
#     (without it: the Upload "Choose files" and Download save panels don't work)
#
# The macos/ folder is generated by `flutter create` (and git-ignored), so run
# this once after generating it, from the app/ directory:
#   bash tool/setup_macos.sh
set -euo pipefail

cd "$(dirname "$0")/.."

patched=0
for f in macos/Runner/DebugProfile.entitlements macos/Runner/Release.entitlements; do
  if [ ! -f "$f" ]; then
    echo "skip: $f not found — run 'flutter create --platforms=macos --org com.gpix --project-name gpix_app .' first"
    continue
  fi
  for key in com.apple.security.network.client com.apple.security.files.user-selected.read-write; do
    /usr/libexec/PlistBuddy -c "Add :$key bool true" "$f" 2>/dev/null \
      || /usr/libexec/PlistBuddy -c "Set :$key true" "$f"
  done
  echo "patched: $f"
  patched=1
done

if [ "$patched" = "1" ]; then
  echo "Done. Now (re)start the app:  flutter run -d macos"
fi
